// futureSchema reports well-formed JSON whose schema_version is one this engine does not read.
func futureSchema(raw []byte) bool {
	var header struct {
		SchemaVersion int `json:"schema_version"`
	}
	if json.Unmarshal(raw, &header) != nil {
		return false
	}
	return header.SchemaVersion > ReviewBundleSchemaVersion
}

func (s Store) VerifyReviewBundle(scope string) (ReviewBundleVerification, error) {
	s = s.reviewOperation()
	verification, err := s.verifyReviewBundle(scope)
	if err == nil && verification.Bundle != nil {
		assurance := s.DescribeReviewAssurance(*verification.Bundle, verification.Attestation)
		verification.Assurance = &assurance
	}
	if err == nil {
		verification.DelegatedRuns, verification.DelegatedHistoryLosses = s.reviewRunSummaries(scope)
	}
	if err == nil && verification.Bundle != nil {
		if round, rerr := s.ReviewRoundOf(*verification.Bundle); rerr != nil {
			verification.DelegatedHistoryLosses = append(verification.DelegatedHistoryLosses, "the round cannot be derived: "+rerr.Error())
		} else {
			verification.Round = round.Number
			policy, _, _, _ := s.LoadDelegationPolicy()
			if threshold := policy.Routing.RoundThresholdOf(); round.Number >= threshold {
				verification.Warnings = append(verification.Warnings, fmt.Sprintf("%s is in review round %d, at or past the round threshold %d: the rounds are not converging; consider a different agent or a human adjudication", scope, round.Number, threshold))
			}
		}
	}
	return verification, err
}

// verifyReviewBundle verifies scope once per operation of the same project and
// resolver, and refuses a scope already being verified: sealed children are
// data, and a cycle among them must end in a named refusal (spec
// pose-review-approval-follows-children R6).
func (s Store) verifyReviewBundle(scope string) (ReviewBundleVerification, error) {
	s = s.reviewOperation()
	state := s.reviewReuse
	key := fmt.Sprintf("%s\x00%t\x00%s", s.Root, s.FederatedResolver != nil, scope)
	if result, ok := state.children[key]; ok {
		return result.verification, result.err
	}
	if state.verifying[key] {
		return ReviewBundleVerification{}, fmt.Errorf("pose: the sealed children of %s form a cycle", scope)
	}
	state.verifying[key] = true
	defer delete(state.verifying, key)
	if s.onReviewVerify != nil {
		s.onReviewVerify(scope)
	}
	verification, err := s.proportionalReviewVerification(scope)
	state.children[key] = childVerificationResult{verification, err}
	return verification, err
}

