		allowed := federatedGitAncestorIn(files, root, subjectHead, evidence.GitHead) &&
			federatedGitAncestorIn(files, root, evidence.GitHead, pinnedHead)
		ancestry[evidence.GitHead] = allowed
		return allowed
	}
}

