   303		if errors.Is(err, posemodel.ErrPublishUnsynced) {
   304			log("warning: governed capabilities adopted, with durability unconfirmed: %v", "aviso: capacidades governadas adotadas, sem durabilidade confirmada: %v", err)
   305		} else if err != nil {
   306			log("warning: governed capabilities not adopted, the policy would be refused: %v", "aviso: capacidades governadas não adotadas, a política seria recusada: %v", err)
   307			return
   308		}
   309		for _, id := range adopted {
   310			log("capability (adoption): %s from %s — `pose adopt %s --off --apply` turns it off", "capacidade (adoção): %s desde %s — `pose adopt %s --off --apply` desliga", id, date, id)
   311		}
   312	}
