   315	// operation's files.
   316	func adoptGovernedCapabilitiesAtInstall(target string, now time.Time, log func(english, portuguese string, a ...any)) {
   317		adoptGovernedCapabilitiesAtInstallIn(posemodel.NativeFiles(), target, now, log)
