   320	// policyPublished reads a policy write: a publication with its durability unconfirmed took
   321	// effect, so it is a warning here and the caller goes on to report what it did.
   322	func policyPublished(err error, stderr io.Writer) error {
   323		if errors.Is(err, posemodel.ErrPublishUnsynced) {
   324			render(stderr, stderr).Finding(cliout.Finding{State: cliout.StateWarning, Code: "policy-durability", Message: err.Error()})
   325			return nil
   326		}
   327		return err
   328	}
